void add_noise(double *wave, double noise = 261.291 * 0.8)
{
    for (int i = 0; i < 100; i++)
    {
        wave[i] += gRandom->Gaus(0, noise);
    }
}


void convert_waveform(TString filename)
{
    TFile *infile = TFile::Open(filename.Data(), "READ");
    DATA_STRUCT Data;
    TTree *tr = (TTree *)infile->Get("ecal");
    tr->SetBranchAddress("EventID", &Data.EventID);
    tr->SetBranchAddress("RunID", &Data.RunID);
    tr->SetBranchAddress("PrimaryParticle", &Data.PrimaryParticle);
    tr->SetBranchAddress("PrimaryEnergy", &Data.PrimaryEnergy);
    tr->SetBranchAddress("PrimaryTime", &Data.PrimaryTime);
    tr->SetBranchAddress("PhotonGeneration", &Data.PhotonGeneration);
    // tr->SetBranchAddress("PhotonWLSConversion", &Data.PhotonWLSConversion);
    // tr->SetBranchAddress("PhotonSelfAbsorption", &Data.PhotonSelfAbsorption);
    // tr->SetBranchAddress("PhotonBoundaryAbsorption", &Data.PhotonBoundaryAbsorption);
    tr->SetBranchAddress("PhotonDetection", &Data.PhotonDetection);
    tr->SetBranchAddress("EnergyDeposition", &Data.EnergyDeposition);
    tr->SetBranchAddress("PhotonEnergyHis", &Data.PhotonEnergyHis);
    tr->SetBranchAddress("PhotonGlobalTimeHis", &Data.PhotonGlobalTimeHis);

    TFile *outfile = TFile::Open(filename.Remove(filename.Last('.')).Append("_withwaveform.root"), "RECREATE");
    TTree *tr_out = tr->CloneTree(0);
    tr_out->SetDirectory(outfile);
    tr_out->SetBranchAddress("EventID", &Data.EventID);
    tr_out->SetBranchAddress("RunID", &Data.RunID);
    tr_out->SetBranchAddress("PrimaryParticle", &Data.PrimaryParticle);
    tr_out->SetBranchAddress("PrimaryEnergy", &Data.PrimaryEnergy);
    tr_out->SetBranchAddress("PrimaryTime", &Data.PrimaryTime);
    tr_out->SetBranchAddress("PhotonGeneration", &Data.PhotonGeneration);
    // tr_out->SetBranchAddress("PhotonWLSConversion", &Data.PhotonWLSConversion);
    // tr_out->SetBranchAddress("PhotonSelfAbsorption", &Data.PhotonSelfAbsorption);
    // tr_out->SetBranchAddress("PhotonBoundaryAbsorption", &Data.PhotonBoundaryAbsorption);
    tr_out->SetBranchAddress("PhotonDetection", &Data.PhotonDetection);
    tr_out->SetBranchAddress("EnergyDeposition", &Data.EnergyDeposition);
    tr_out->SetBranchAddress("PhotonEnergyHis", &Data.PhotonEnergyHis);
    tr_out->SetBranchAddress("PhotonGlobalTimeHis", &Data.PhotonGlobalTimeHis);
    tr_out->Branch("Waveform", &Data.Waveform, "Waveform[100]/D");
    tr_out->Branch("WaveformNoise", &Data.WaveformNoise, "WaveformNoise[100]/D");

    double photon[5000], wave[12500]; // 0.1 ns bin width
    int eventNum = tr->GetEntries();
    for (int i = 0; i < eventNum; i++)
    {
        std::cout << "\rProcessing " << i << " events.";
        std::cout.flush();
        tr->GetEntry(i);
        memset(photon, 0, sizeof(photon));
        memset(wave, 0, sizeof(wave));
        for (int j = 0; j < 5000; j++)
            photon[j] = Data.PhotonGlobalTimeHis[j];
        ConvoluteIRF(photon, wave);
        for (int i = 0; i < 100; i++)
        {
            Data.Waveform[i] = wave[i * 125];
            Data.WaveformNoise[i] = wave[i * 125];
        }
        add_noise(Data.WaveformNoise);
        tr_out->Fill();
    }
    infile->Close();
    outfile->Write();
    outfile->Close();
}


int main(int argc, char *argv[])
{
    if (argc != 2)
    {
        std::cout << "Usage: " << argv[0] << " <input.root>" << std::endl;
        return 1;
    }
    convert_waveform(argv[1]);
    return 0;
}
